#!/usr/bin/env node
// plan-board: the index of plans for the plan supervisor (prototype, v0).
//
// Sources, one writer each:
//   plans/<id>/plan.md frontmatter  -> planner   (status, priority, blockedBy, footprint, base)
//   <state dir>/state.json          -> supervisor (leader per plan)
//   plans/board.md                  -> generated by `render --write`, never edited by hand
// Progress of a running plan is read from `fgos workflow status <caseId>`, not from here.
import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync, appendFileSync, statSync, unlinkSync, utimesSync, realpathSync } from 'node:fs';
import { join, resolve, basename, dirname } from 'node:path';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { homedir } from 'node:os';

const KNOWN_STATUS = ['draft', 'todo', 'in-progress', 'completed', 'archived', 'cancelled'];
// ak:plan plans in the wild also write `done`; read it as `completed`.
const STATUS_ALIAS = { done: 'completed' };
const PRIORITY = { P0: 0, P1: 1, P2: 2, P3: 3 };

export function parseFrontmatter(text) {
  const m = /^---\r?\n([\s\S]*?)\r?\n---/.exec(text);
  if (!m) return {};
  const out = {};
  for (const line of m[1].split(/\r?\n/)) {
    const kv = /^([A-Za-z_][\w-]*):\s*(.*)$/.exec(line);
    if (!kv) continue;
    out[kv[1]] = parseValue(kv[2].trim());
  }
  return out;
}

function parseValue(v) {
  if (v.startsWith('[') && v.endsWith(']')) {
    const inner = v.slice(1, -1).trim();
    return inner === '' ? [] : inner.split(',').map((s) => unquote(s.trim()));
  }
  return unquote(v);
}
const unquote = (s) => (/^(["']).*\1$/.test(s) ? s.slice(1, -1) : s);

export function readPlans(plansDir) {
  const plans = [];
  for (const name of readdirSync(plansDir).sort()) {
    const dir = join(plansDir, name);
    const file = join(dir, 'plan.md');
    if (!statSync(dir).isDirectory() || !existsSync(file)) continue;
    const fm = parseFrontmatter(readFileSync(file, 'utf8'));
    plans.push({
      id: name,
      title: fm.title ?? name,
      status: STATUS_ALIAS[fm.status] ?? fm.status ?? '',
      priority: fm.priority ?? 'P3',
      blockedBy: Array.isArray(fm.blockedBy) ? [...fm.blockedBy] : [],
      blocks: Array.isArray(fm.blocks) ? fm.blocks : [],
      footprint: Array.isArray(fm.footprint) ? fm.footprint : null,
      base: fm.base ?? null,
      created: fm.created ?? '',
    });
  }
  // `blocks` is the reverse edge: if A blocks B, then B waits for A.
  const byId = new Map(plans.map((p) => [p.id, p]));
  for (const p of plans) for (const t of p.blocks) {
    const target = byId.get(t);
    if (target && !target.blockedBy.includes(p.id)) target.blockedBy.push(p.id);
  }
  return plans;
}

const norm = (p) => p.replace(/\\/g, '/').replace(/\*\*?.*$/, '').replace(/\/+$/, '');
export function overlaps(a, b) {
  return a.some((x) => b.some((y) => {
    const nx = norm(x), ny = norm(y);
    return nx === '' || ny === '' || nx === ny || nx.startsWith(ny + '/') || ny.startsWith(nx + '/');
  }));
}

export function stateDirFor(plansDir) {
  if (process.env.PLAN_SUPERVISOR_STATE) return process.env.PLAN_SUPERVISOR_STATE;
  // One state dir per project. Named after the folder; if another project with the same folder name already owns that
  // dir (recorded in project.txt), this project gets a dir with a short hash of its path instead.
  const project = dirname(resolve(plansDir));
  const base = join(process.env.XDG_STATE_HOME ?? join(homedir(), '.local/state'), 'plan-supervisor');
  const plain = join(base, basename(project));
  const marker = join(plain, 'project.txt');
  if (existsSync(marker) && readFileSync(marker, 'utf8').trim() !== project) {
    return join(base, `${basename(project)}-${createHash('sha1').update(project).digest('hex').slice(0, 8)}`);
  }
  return plain;
}

export function readConfig(stateDir) {
  const f = join(stateDir, 'config.json');
  return existsSync(f) ? JSON.parse(readFileSync(f, 'utf8')) : {};
}

export function readState(stateDir) {
  const f = join(stateDir, 'state.json');
  if (!existsSync(f)) return { leaders: {} };
  const s = JSON.parse(readFileSync(f, 'utf8'));
  return { leaders: s.leaders ?? {} };
}
// Newest modification time under a directory, bounded so a huge run directory stays cheap.
function newestMtime(root, budget = { n: 4000 }) {
  let newest = statSync(root).mtimeMs;
  for (const e of readdirSync(root, { withFileTypes: true })) {
    if (budget.n-- <= 0) break;
    const p = join(root, e.name);
    const m = e.isDirectory() ? newestMtime(p, budget) : statSync(p).mtimeMs;
    if (m > newest) newest = m;
  }
  return newest;
}

function readTsv(file) {
  return existsSync(file) ? readFileSync(file, 'utf8').split('\n').filter(Boolean).map((l) => l.split('\t')) : [];
}
const minutes = (ms) => +(ms / 60000).toFixed(1);

// Objective "three things" check of one commit (AGENTS.md of the pilot project): a unit test, an e2e test on the binary,
// and the guide (README or docs) in the same change. Read from git, never from the worker's word.
export function commitFacts(repo, sha) {
  const git = (...a) => spawnSync('git', ['-C', repo, ...a], { encoding: 'utf8' }).stdout ?? '';
  const files = git('show', '--numstat', '--format=', sha).split('\n').filter(Boolean).map((l) => l.split('\t')[2]);
  const added = git('show', '--format=', '-U0', sha).split('\n').filter((l) => l.startsWith('+')).join('\n');
  const isTestFile = (f) => /(^|\/)tests?\//.test(f) || /\/tests\.rs$/.test(f);
  const unit = files.some((f) => /\/src\/.*tests?\.rs$|\/src\/.*tests\//.test(f)) || /#\[test\]/.test(added);
  const e2e = files.some((f) => /^apps\/[^/]+\/tests\//.test(f) || /^examples\/[^/]+\/tests\//.test(f) || /\/tests\/[^/]+\.rs$/.test(f) && isTestFile(f));
  const doc = files.some((f) => f === 'README.md' || f.startsWith('docs/'));
  return { files: files.length, unit, e2e, doc };
}

function readQueue(stateDir) {
  const f = join(stateDir, 'queue.jsonl');
  if (!existsSync(f)) return [];
  return readFileSync(f, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));
}
function writeState(stateDir, state) {
  mkdirSync(stateDir, { recursive: true });
  writeFileSync(join(stateDir, 'state.json'), JSON.stringify(state, null, 2) + '\n');
}

// Lanes: a lane is one concurrently live dispatch. A running plan uses `lanes.get(id)` lanes (read from its case), at least 1.
// The cap is on lanes, and plans are admitted in priority order until the remaining lanes run out.
export function analyse(plans, state, { maxLanes = 1, lanes = new Map() } = {}) {
  const byId = new Map(plans.map((p) => [p.id, p]));
  const problems = [];
  const warnings = [];
  for (const p of plans) {
    if (!KNOWN_STATUS.includes(p.status)) problems.push(`${p.id}: unknown status "${p.status}"`);
    if (!(p.priority in PRIORITY)) warnings.push(`${p.id}: unknown priority "${p.priority}"`);
    for (const b of p.blockedBy) if (!byId.has(b)) problems.push(`${p.id}: blockedBy names unknown plan ${b}`);
    if (p.status === 'todo' && !p.footprint) warnings.push(`${p.id}: no footprint (cannot run beside another plan)`);
    if (p.status === 'todo' && !p.base) warnings.push(`${p.id}: no base commit (cannot detect drift)`);
  }
  for (const id of Object.keys(state.leaders)) {
    const p = byId.get(id);
    if (!p) problems.push(`state: leader recorded for missing plan ${id}`);
    else if (p.status === 'completed') problems.push(`${id}: completed but still has leader ${state.leaders[id].caseId}`);
  }
  const running = plans.filter((p) => state.leaders[p.id]);
  for (let i = 0; i < running.length; i++) for (let j = i + 1; j < running.length; j++) {
    const a = running[i], b = running[j];
    if (!a.footprint || !b.footprint || overlaps(a.footprint, b.footprint)) {
      problems.push(`${a.id} and ${b.id} run together but their footprints overlap or are unknown`);
    }
  }
  const cycle = findCycle(plans);
  if (cycle) problems.push(`blockedBy cycle: ${cycle.join(' -> ')}`);

  const laneOf = (id) => Math.max(1, lanes.get(id) ?? 1);
  const usedLanes = running.reduce((t, r) => t + laneOf(r.id), 0);
  let free = maxLanes - usedLanes;
  const eligible = [];
  const held = [];
  const rank = (a, b) => (PRIORITY[a.priority] ?? 9) - (PRIORITY[b.priority] ?? 9) || a.created.localeCompare(b.created) || a.id.localeCompare(b.id);
  const candidates = plans.filter((p) => p.status === 'todo' && !state.leaders[p.id]).sort(rank);
  for (const p of candidates) {
    const waiting = p.blockedBy.filter((b) => byId.get(b)?.status !== 'completed');
    if (waiting.length) { held.push({ id: p.id, why: `waits for ${waiting.join(', ')}` }); continue; }
    if (free < 1) { held.push({ id: p.id, why: `no free lane (${usedLanes + eligible.length}/${maxLanes} in use or reserved)` }); continue; }
    // footprints must be disjoint from running plans and from plans admitted earlier in this pass
    const others = [...running, ...eligible];
    const clash = others.length ? others.find((r) => !r.footprint || !p.footprint || overlaps(r.footprint, p.footprint)) : null;
    if (clash) { held.push({ id: p.id, why: `footprint unknown or overlaps ${clash.id}` }); continue; }
    eligible.push(p);
    free -= 1;
  }
  return { problems, warnings, eligible, held, running, lanes: { used: usedLanes, max: maxLanes, free: Math.max(0, maxLanes - usedLanes), admitted: eligible.length } };
}

function findCycle(plans) {
  const next = new Map(plans.map((p) => [p.id, p.blockedBy]));
  const state = new Map();
  const path = [];
  const visit = (id) => {
    if (state.get(id) === 2) return null;
    if (state.get(id) === 1) return [...path.slice(path.indexOf(id)), id];
    state.set(id, 1); path.push(id);
    for (const n of next.get(id) ?? []) { if (!next.has(n)) continue; const c = visit(n); if (c) return c; }
    path.pop(); state.set(id, 2);
    return null;
  };
  for (const id of next.keys()) { const c = visit(id); if (c) return c; }
  return null;
}

export function renderBoard(plans, state, result) {
  const rows = plans.map((p) => {
    const l = state.leaders[p.id];
    const shown = l ? 'running' : result.eligible.includes(p) ? 'ready' : p.status;
    return `| ${p.id} | ${p.title.replace(/\|/g, '/')} | ${shown} | ${p.priority} | ${p.blockedBy.join(', ') || '-'} | ${(p.footprint ?? ['?']).join(', ')} | ${l ? l.caseId : '-'} |`;
  });
  return [
    '# Plan board',
    '',
    'Generated by `plan-board.mjs render --write`. Do not edit by hand: change the plan frontmatter, then regenerate.',
    'Progress of a running plan is read with `fgos workflow status <leader>`, never copied here.',
    '',
    '| Plan | Title | State | Priority | Blocked by | Footprint | Leader |',
    '|---|---|---|---|---|---|---|',
    ...rows,
    '',
  ].join('\n');
}

function parseArgs(argv) {
  const flags = {};
  const rest = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith('--')) {
      const k = a.slice(2);
      if (['json', 'write', 'mark', 'baseline'].includes(k)) flags[k] = true; else flags[k] = argv[++i];
    } else rest.push(a);
  }
  return { flags, rest };
}

const NEEDS_PLANS = new Set(['check', 'eligible', 'render', 'claim', 'release']);

export function main(argv, out = console.log) {
  const { flags, rest } = parseArgs(argv);
  const [cmd, ...args] = rest;
  const plansDir = resolve(flags.root ?? 'plans');
  if (NEEDS_PLANS.has(cmd) && !existsSync(plansDir)) { out(`no plans directory at ${plansDir}`); return 2; }
  const stateDir = stateDirFor(plansDir);
  const projectRoot = dirname(plansDir);
  const ensureState = () => {
    mkdirSync(stateDir, { recursive: true });
    const marker = join(stateDir, 'project.txt');
    if (!existsSync(marker)) writeFileSync(marker, projectRoot + '\n');
  };
  const plans = existsSync(plansDir) ? readPlans(plansDir) : [];
  const state = readState(stateDir);
  const cfg = readConfig(stateDir);
  // `maxRunning` is the old name of the same setting (it used to count plans); one running plan counts as one lane.
  const maxLanes = Number(flags['max-lanes'] ?? flags['max-running'] ?? cfg.maxLanes ?? cfg.maxRunning ?? 1);
  const lanes = new Map();
  const fgosForLanes = process.env.PLAN_SUPERVISOR_FGOS ?? join(projectRoot, '.fgos', 'installation', 'bin', 'fgos');
  if (existsSync(fgosForLanes)) {
    for (const [id, l] of Object.entries(state.leaders)) {
      if (!/^wf-run-/.test(l.caseId)) continue;
      try {
        const r = spawnSync(fgosForLanes, ['workflow', 'status', l.caseId, '--json'], { cwd: projectRoot, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'], timeout: 20000 });
        lanes.set(id, JSON.parse(r.stdout).data.case.liveReservations.length);
      } catch { /* unreadable: counts as one lane */ }
    }
  }
  const result = analyse(plans, state, { maxLanes, lanes });

  switch (cmd) {
    case 'check':
      for (const w of result.warnings) out(`warning: ${w}`);
      for (const p of result.problems) out(`error: ${p}`);
      return result.problems.length ? 1 : 0;
    case 'eligible':
      if (flags.json) out(JSON.stringify({ eligible: result.eligible.map((p) => p.id), held: result.held, running: result.running.map((p) => p.id), lanes: result.lanes, problems: result.problems }, null, 2));
      else {
        out(`lanes ${result.lanes.used}/${result.lanes.max} in use, ${result.lanes.free} free, ${result.lanes.admitted} plan(s) can start now`);
        for (const p of result.eligible) out(`${p.id}\t${p.priority}\t${p.title}`);
        for (const h of result.held) out(`held ${h.id}: ${h.why}`);
      }
      return 0;
    case 'render': {
      const text = renderBoard(plans, state, result);
      if (flags.write) writeFileSync(join(plansDir, 'board.md'), text); else out(text);
      return 0;
    }
    case 'claim': {
      const [id, caseId] = args;
      if (!id || !caseId) { out('usage: claim <plan-id> <leader-id>'); return 2; }
      if (!plans.some((p) => p.id === id)) { out(`unknown plan ${id}`); return 2; }
      if (state.leaders[id]) { out(`${id} already held by ${state.leaders[id].caseId}`); return 0; }
      state.leaders[id] = { caseId, since: new Date().toISOString() };
      ensureState();
      writeState(stateDir, state);
      out(`claimed ${id} for ${caseId}`);
      return 0;
    }
    case 'release': {
      const [id] = args;
      if (!state.leaders[id]) { out(`${id} has no leader`); return 0; }
      delete state.leaders[id];
      ensureState();
      writeState(stateDir, state);
      out(`released ${id}`);
      return 0;
    }
    case 'health': {
      // Watchdog for a running case: list unit runs of the case from .fgos/assignments and flag failures.
      // Exit 4 when any unit run ended execution-failure / infrastructure failure, so a tick cannot miss it.
      const caseId = flags.case;
      const dir = join(resolve(flags.fgos ?? '.fgos'), 'assignments');
      if (!caseId || !existsSync(dir)) { out('usage: health --case <caseId> [--fgos .fgos]'); return 2; }
      const rows = [];
      for (const u of readdirSync(dir)) {
        const f = join(dir, u, 'unit-summary.json');
        const live = existsSync(join(dir, u, 'unit.json'));
        if (!live) continue;
        const sum = existsSync(f) ? JSON.parse(readFileSync(f, 'utf8')) : null;
        const unit = JSON.parse(readFileSync(join(dir, u, 'unit.json'), 'utf8'));
        const c = sum?.workflow?.caseId ?? unit.workflow?.caseId ?? unit.caseId;
        if (c !== caseId) continue;
        rows.push({ run: u, activity: sum?.workflow?.activity ?? unit.workflow?.activity ?? '?', outcome: sum?.outcome ?? 'running',
          reason: sum?.infrastructureReason ?? '', startedAt: sum?.startedAt ?? '', settledAt: sum?.settledAt ?? '' });
      }
      rows.sort((a, b) => a.run.localeCompare(b.run));
      for (const r of rows) out(`${r.run}\t${r.activity}\t${r.outcome}\t${r.reason}\t${r.startedAt}\t${r.settledAt}`);
      const failed = rows.filter((r) => r.outcome === 'execution-failure' || r.reason);
      if (failed.length) { out(`FAILED: ${failed.map((r) => `${r.activity} (${r.reason || r.outcome})`).join(', ')}`); return 4; }
      return 0;
    }
    case 'config': {
      // Per-project settings kept in the state dir: maxLanes (concurrent live dispatches over all running plans), stallMin.
      const [action, key, value] = args;
      const KEYS = { maxLanes: 'number', maxRunning: 'number', stallMin: 'number' };
      if (action === 'set' && key in KEYS && value !== undefined && !Number.isNaN(Number(value)) && Number(value) > 0) {
        ensureState();
        const name = key === 'maxRunning' ? 'maxLanes' : key;   // old name, same setting
        const { maxRunning: _old, ...rest } = cfg;
        writeFileSync(join(stateDir, 'config.json'), JSON.stringify({ ...rest, [name]: Number(value) }, null, 2) + '\n');
        out(`${name} = ${Number(value)}`);
        return 0;
      }
      if (action === 'get' || action === undefined) { out(JSON.stringify({ maxLanes, stallMin: cfg.stallMin ?? 20, stateDir, project: projectRoot })); return 0; }
      out('usage: config [get] | config set <maxLanes|stallMin> <positive number>');
      return 2;
    }
    case 'doctor': {
      // Is this project ready for the supervisor? Prints one line per check; changes nothing. Exit 1 if a required check fails.
      const lines = [];
      const add = (ok, required, what, fix) => lines.push({ ok, required, text: `${ok ? 'ok  ' : required ? 'TODO' : 'warn'} ${what}${ok ? '' : ' -> ' + fix}` });
      const fgosBin = join(projectRoot, '.fgos', 'installation', 'bin', 'fgos');
      const inited = existsSync(fgosBin);
      add(inited, true, 'fgOS initialised in the project', 'run `fgctl init` in the project');
      if (inited) {
        const r = spawnSync(fgosBin, ['config', 'show', '--path', 'runner.capabilities.code:implement.verify', '--json'], { cwd: projectRoot, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
        let present = false;
        try { present = JSON.parse(r.stdout).data.present === true; } catch { /* unknown */ }
        add(present, true, 'whole-tree gate declared (runner.capabilities.code:implement.verify)', "`fgos config set 'runner.capabilities.code:implement.verify' '<command>' --reason '<why>'`");
      }
      // Claude Code asks "do you trust this folder?" once per project; a seat that runs in a pane stalls on that prompt
      // (observed: terminal:delivery-unknown). Git worktrees of a trusted repo were not asked, so check the main folder.
      let trusted = false;
      try {
        const cj = JSON.parse(readFileSync(process.env.CLAUDE_JSON ?? join(homedir(), '.claude.json'), 'utf8'));
        trusted = cj.projects?.[realpathSync(projectRoot)]?.hasTrustDialogAccepted === true;
      } catch { /* no Claude config: treat as untrusted */ }
      add(trusted, true, 'Claude Code trusts this folder', 'open `claude` once in the project and accept the trust prompt (a security decision only you can make; seats stall on it otherwise)');
      add(existsSync(join(projectRoot, '.fgos', 'assignments')), false, '.fgos/assignments exists (appears after the first fgOS run)', 'run any `fgos run` once; the watchdog needs it');
      const hasPlans = plans.length > 0;
      add(hasPlans, false, `plans/ has plans (${plans.length})`, 'create plans with ak:plan; the supervisor tick needs them, the watchdog does not');
      const missing = plans.filter((p) => p.status === 'todo' && (!p.footprint || !p.base)).map((p) => p.id);
      if (hasPlans) add(missing.length === 0, false, `todo plans declare footprint and base${missing.length ? ' (' + missing.length + ' do not)' : ''}`, 'add `footprint: [paths]` and `base: <commit>` to their frontmatter so they can run side by side');
      const ign = spawnSync('git', ['-C', projectRoot, 'check-ignore', '-q', '.fgos'], { encoding: 'utf8' });
      add(ign.status === 0, false, '.fgos is ignored by git', 'add `/.fgos/` to .gitignore');
      add(true, false, `settings: maxLanes ${maxLanes}, stallMin ${cfg.stallMin ?? 20} (change: plan-board.mjs config set ...)`, '');
      for (const l of lines) out(l.text);
      return lines.some((l) => !l.ok && l.required) ? 1 : 0;
    }
    case 'verify': {
      // Conductor's independent check: verify <case> <slice|plan> <pass|fail> <note...> [k=v ...] [--commit SHA --repo DIR --at ISO]
      // Extras (k=v): gates=fmt+clippy+test|none  widened=N  needswrites=N  mismatch=N (worker claim contradicted by my re-run)
      //               deviation=N (worker left the brief)  kind=premise|underspecified|missing-dep (for slice=plan)
      const [caseId, slice, result, ...rest] = args;
      if (!caseId || !slice || !['pass', 'fail'].includes(result)) { out('usage: verify <case> <slice|plan> <pass|fail> <note> [k=v...] [--commit SHA --repo DIR --at ISO]'); return 2; }
      const extras = {};
      const note = [];
      for (const t of rest) { const m = /^([a-z_]+)=(\S*)$/.exec(t); if (m) extras[m[1]] = m[2]; else note.push(t); }
      if (flags.commit) extras.facts = commitFacts(resolve(flags.repo ?? '.'), flags.commit);
      ensureState();
      appendFileSync(join(stateDir, 'verifications.tsv'), [flags.at ?? new Date().toISOString(), caseId, slice, result, note.join(' '), JSON.stringify(extras)].join('\t') + '\n');
      out(`recorded ${slice} ${result}${extras.facts ? ' facts=' + JSON.stringify(extras.facts) : ''}`);
      return 0;
    }
    case 'event': {
      // event <case> <assigned|note...>: timestamps the report cannot read from fgOS (e.g. when the owner handed the work over)
      const [caseId, kind, ...note] = args;
      if (!caseId || !kind) { out('usage: event <case> <kind> [note] [--at ISO]'); return 2; }
      ensureState();
      appendFileSync(join(stateDir, 'events.tsv'), [flags.at ?? new Date().toISOString(), caseId, kind, note.join(' ')].join('\t') + '\n');
      out(`event ${kind} recorded`);
      return 0;
    }
    case 'sessions': {
      // Length of the Claude Code sessions of this project, from their transcripts (a no-token proxy for context growth).
      const proj = resolve(flags.project ?? process.cwd());
      const tdir = join(flags.transcripts ?? join(homedir(), '.claude', 'projects'), proj.replace(/[\/_.]/g, '-'));
      if (!existsSync(tdir)) { out(`no transcripts at ${tdir}`); return 0; }
      const rows = readdirSync(tdir).filter((f) => f.endsWith('.jsonl')).map((f) => {
        const full = join(tdir, f);
        let lines = 0, assistant = 0, first = '', last = '';
        for (const l of readFileSync(full, 'utf8').split('\n')) {
          if (!l) continue;
          lines++;
          try { const j = JSON.parse(l); if (j.type === 'assistant') assistant++; if (j.timestamp) { first ||= j.timestamp; last = j.timestamp; } } catch { /* skip */ }
        }
        return { session: f.replace(/\.jsonl$/, ''), mb: +(statSync(full).size / 1048576).toFixed(2), lines, assistant, first, last, mtime: statSync(full).mtimeMs };
      }).sort((a, b) => b.mb - a.mb);
      if (flags.label) {
        const cur = [...rows].sort((a, b) => b.mtime - a.mtime)[0];
        ensureState();
        appendFileSync(join(stateDir, 'session-marks.tsv'), [new Date().toISOString(), flags.label, cur.session, cur.mb, cur.lines, cur.assistant].join('\t') + '\n');
        out(`mark ${flags.label}: ${cur.session} ${cur.mb} MB, ${cur.assistant} assistant messages`);
        return 0;
      }
      if (flags.json) { out(JSON.stringify(rows.map(({ mtime, ...r }) => r), null, 2)); return 0; }
      for (const r of rows) out(`${r.session}\t${r.mb} MB\t${r.lines} lines\t${r.assistant} assistant msgs\t${r.first.slice(0, 16)} .. ${r.last.slice(0, 16)}`);
      return 0;
    }
    case 'report': {
      // Seven measures from files only (no LLM, no tokens): completion, lead time, interventions, scope fidelity, plan
      // defects, detection latency, gates at the first independent check; plus session length via `sessions`.
      const dir = join(resolve(flags.fgos ?? '.fgos'), 'assignments');
      if (!existsSync(dir)) { out('no .fgos/assignments here'); return 0; }
      const checks = readTsv(join(stateDir, 'verifications.tsv')).map(([at, c, slice, res, note, ex]) => ({ at: Date.parse(at), case: c, slice, result: res, note, ex: ex ? JSON.parse(ex) : {} }));
      const events = readTsv(join(stateDir, 'events.tsv')).map(([at, c, kind, note]) => ({ at: Date.parse(at), case: c, kind, note }));
      const queue = readQueue(stateDir);
      const detections = readTsv(join(stateDir, 'detections.tsv')).filter((r) => r[4] !== '').map((r) => ({ kind: r[2], latency: Number(r[4]) }));
      const BADSET = new Set(['execution-failure', 'policy-refusal', 'provider-limit', 'blocked']);
      const cases = new Map();
      for (const u of readdirSync(dir)) {
        const f = join(dir, u, 'unit-summary.json');
        if (!existsSync(f)) continue;
        const sum = JSON.parse(readFileSync(f, 'utf8'));
        const c = sum.workflow?.caseId ?? 'standalone';
        if (flags.case && c !== flags.case) continue;
        if (!cases.has(c)) cases.set(c, []);
        cases.get(c).push({ activity: sum.workflow?.activity ?? '?', outcome: sum.outcome, start: Date.parse(sum.startedAt), end: Date.parse(sum.settledAt) });
      }
      const union = (list) => { let t = 0, cur = -Infinity; for (const x of [...list].sort((a, b) => a.start - b.start)) { const from = Math.max(x.start, cur); if (x.end > from) t += x.end - from; cur = Math.max(cur, x.end); } return t; };
      const fgosBin = join(resolve(flags.fgos ?? '.fgos'), 'installation', 'bin', 'fgos');
      const median = (a) => { if (!a.length) return null; const v = [...a].sort((x, y) => x - y); return v[Math.floor(v.length / 2)]; };
      const result = [];
      for (const [id, units] of cases) {
        if (id === 'standalone') continue;
        units.sort((a, b) => a.start - b.start);
        const ok = units.filter((x) => x.outcome === 'pass').length;
        const badRuns = units.filter((x) => BADSET.has(x.outcome));
        const reruns = [...units.reduce((m, x) => m.set(x.activity, (m.get(x.activity) ?? 0) + 1), new Map()).values()].reduce((a, n) => a + Math.max(0, n - 1), 0);
        const mine = checks.filter((c) => c.case === id);
        const sliceChecks = mine.filter((c) => c.slice !== 'plan');
        const planChecks = mine.filter((c) => c.slice === 'plan' && c.result === 'fail');
        // completion
        let milestones = null;
        if (existsSync(fgosBin)) {
          try {
            const r = spawnSync(fgosBin, ['workflow', 'status', id, '--json'], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
            milestones = Object.fromEntries(Object.entries(JSON.parse(r.stdout).data.case.milestones).map(([k, v]) => [k, v.state]));
          } catch { /* leave null */ }
        }
        // lead time from the hand-over to the last passing independent check
        const assignedEv = events.find((e) => e.case === id && e.kind === 'assigned');
        const assigned = assignedEv?.at ?? units[0].start;
        const passAt = sliceChecks.filter((c) => c.result === 'pass').map((c) => c.at);
        const done = passAt.length ? Math.max(...passAt) : null;
        let lead = null;
        if (done) {
          const worker = union(units.filter((x) => !BADSET.has(x.outcome)));
          const failed = badRuns.reduce((t, x) => t + (x.end - x.start), 0);
          let verif = 0;
          const usedUnits = new Set();
          for (const c of [...sliceChecks].sort((x, y) => x.at - y.at)) { const prev = units.filter((x) => x.activity === 'implement-item' && x.end <= c.at).at(-1); if (prev && !usedUnits.has(prev)) { usedUnits.add(prev); verif += c.at - prev.end; } }
          let wait = 0;
          for (const q of queue) { const qa = Date.parse(q.at), qb = q.answeredAt ? Date.parse(q.answeredAt) : NaN; if (qa >= assigned && qa <= done && !Number.isNaN(qb)) wait += Math.min(qb, done) - qa; }
          const total = done - assigned;
          lead = { from: assignedEv ? 'event assigned' : 'first run', total_min: minutes(total), worker_min: minutes(worker), failed_runs_min: minutes(failed),
            verification_min: minutes(verif), owner_wait_min: minutes(wait), other_min: minutes(Math.max(0, total - worker - failed - verif - wait)) };
        }
        const gateOk = (c) => { const g = c.ex.gates; return g && g !== 'none' && ['fmt', 'clippy', 'test'].every((x) => g.split('+').includes(x)); };
        const three = (c) => c.ex.facts && c.ex.facts.unit && c.ex.facts.e2e && c.ex.facts.doc;
        const sum = (k) => sliceChecks.reduce((t, c) => t + Number(c.ex[k] ?? 0), 0);
        result.push({
          case: id, runs: units.length,
          completion: { achieved: milestones ? Object.values(milestones).filter((v) => v === 'achieved').length : null, of: milestones ? Object.keys(milestones).length : null, milestones },
          lead_time: lead,
          gates_at_first_independent_check: { slices: sliceChecks.length, all_gates: sliceChecks.filter(gateOk).length, three_things: sliceChecks.filter(three).length,
            missing: sliceChecks.filter((c) => c.ex.facts && !three(c)).map((c) => `${c.slice}:${['unit', 'e2e', 'doc'].filter((k) => !c.ex.facts[k]).join('+')}`) },
          scope_fidelity: { widened_paths: sum('widened'), needs_writes: sum('needswrites'), worker_claims_contradicted: sum('mismatch'), brief_deviations: sum('deviation') },
          plan_defects: { total: planChecks.length, by_kind: planChecks.reduce((m, c) => ({ ...m, [c.ex.kind ?? 'unclassified']: (m[c.ex.kind ?? 'unclassified'] ?? 0) + 1 }), {}) },
          fgos_runs: { pass: `${ok}/${ok + badRuns.length}`, failed_or_refused: badRuns.length, reruns_of_same_step: reruns, independent_checks_passed: `${sliceChecks.filter((c) => c.result === 'pass').length}/${sliceChecks.length}` },
        });
      }
      const answered = queue.filter((q) => q.answeredAt);
      const waits = answered.map((q) => minutes(Date.parse(q.answeredAt) - Date.parse(q.at)));
      const interventions = { items: queue.length, open: queue.filter((q) => !q.done).length, by_kind: queue.reduce((m, q) => ({ ...m, [q.kind ?? 'unknown']: (m[q.kind ?? 'unknown'] ?? 0) + 1 }), {}), median_wait_min: median(waits), answered_with_time: answered.length };
      const detection = { alerts: detections.length, median_latency_min: median(detections.map((d) => d.latency)), max_latency_min: detections.length ? Math.max(...detections.map((d) => d.latency)) : null };
      const marks = readTsv(join(stateDir, 'session-marks.tsv')).map(([at, label, session, mb, lines, assistant]) => ({ at, label, session: session.slice(0, 8), mb: Number(mb), lines: Number(lines), assistant: Number(assistant) }));
      const whole = { cases: result, interventions, detection_latency: detection, session_marks: marks };
      if (flags.json) { out(JSON.stringify(whole, null, 2)); return 0; }
      for (const r of result) {
        out(`case ${r.case}  (${r.runs} fgOS runs)`);
        out(`  1 completion      ${r.completion.achieved ?? '?'}/${r.completion.of ?? '?'} milestones${r.completion.milestones ? ' (' + Object.entries(r.completion.milestones).filter(([, v]) => v === 'achieved').map(([k]) => k).join(', ') + ')' : ''}`);
        out(`  2 lead time       ${r.lead_time ? `${r.lead_time.total_min} min from ${r.lead_time.from} = worker ${r.lead_time.worker_min} + failed runs ${r.lead_time.failed_runs_min} + my verification ${r.lead_time.verification_min} + owner wait ${r.lead_time.owner_wait_min} + other ${r.lead_time.other_min}` : 'n/a (no passing independent check yet)'}`);
        out(`  4 scope fidelity  widened paths ${r.scope_fidelity.widened_paths}, needsWrites ${r.scope_fidelity.needs_writes}, worker claims contradicted ${r.scope_fidelity.worker_claims_contradicted}, brief deviations ${r.scope_fidelity.brief_deviations}`);
        out(`  5 plan defects    ${r.plan_defects.total} ${JSON.stringify(r.plan_defects.by_kind)}`);
        const g = r.gates_at_first_independent_check;
        out(`  7 first check     gates (fmt+clippy+test) ${g.all_gates}/${g.slices}; fmt-clippy-test aside, unit+e2e+doc in the commit ${g.three_things}/${g.slices}${g.missing.length ? ' missing ' + g.missing.join(' ') : ''}`);
        out(`    fgOS runs: pass ${r.fgos_runs.pass}, failed/refused ${r.fgos_runs.failed_or_refused}, step reruns ${r.fgos_runs.reruns_of_same_step}, independent checks ${r.fgos_runs.independent_checks_passed}`);
      }
      out(`3 interventions   ${interventions.items} items (${interventions.open} open) ${JSON.stringify(interventions.by_kind)}; median wait ${interventions.median_wait_min ?? 'n/a'} min over ${interventions.answered_with_time} answered with a time`);
      out(`6 detection       ${detection.alerts} detections (watchdog, or found by the owner first); median latency ${detection.median_latency_min ?? 'n/a'} min, max ${detection.max_latency_min ?? 'n/a'} min`);
      for (const m of marks) out(`1b session length  ${m.label}: ${m.mb} MB, ${m.assistant} assistant messages (${m.session})`);
      return 0;
    }
    case 'watch': {
      // Cheap, LLM-free watchdog over every unit run under .fgos/assignments (any case, any leader, run by hand or not).
      // Alerts once per unit run: a run that ended badly, or a live run whose files have not changed for --stall-min.
      // `--baseline` marks everything present as seen without alerting (first install). Exit 4 = new alerts.
      const dir = join(resolve(flags.fgos ?? '.fgos'), 'assignments');
      if (!existsSync(dir)) { out('no .fgos/assignments here'); return 0; }
      const stallMs = Number(flags['stall-min'] ?? cfg.stallMin ?? 20) * 60_000;
      const seenFile = join(stateDir, 'seen.json');
      const seen = new Set(existsSync(seenFile) ? JSON.parse(readFileSync(seenFile, 'utf8')) : []);
      const BAD = new Set(['execution-failure', 'policy-refusal', 'provider-limit', 'blocked']);
      const alerts = [];
      for (const u of readdirSync(dir)) {
        const root = join(dir, u);
        if (!existsSync(join(root, 'unit.json'))) continue;
        const sumFile = join(root, 'unit-summary.json');
        const sum = existsSync(sumFile) ? JSON.parse(readFileSync(sumFile, 'utf8')) : null;
        const activity = sum?.workflow?.activity ?? '?';
        if (sum) {
          if ((BAD.has(sum.outcome) || sum.infrastructure) && !seen.has(`${u}:failed`)) {
            alerts.push({ key: `${u}:failed`, kind: 'failed', eventAt: Date.parse(sum.settledAt), line: `ALERT failed ${u} ${activity} ${sum.outcome}${sum.infrastructureReason ? ' ' + sum.infrastructureReason : ''}` });
          }
        } else {
          const idle = Date.now() - newestMtime(root);
          if (idle > stallMs && !seen.has(`${u}:stalled`)) {
            alerts.push({ key: `${u}:stalled`, kind: 'stalled', eventAt: Date.now() - idle, line: `ALERT stalled ${u} ${activity} no file change for ${Math.round(idle / 60000)} min` });
          }
        }
      }
      ensureState();
      for (const a of alerts) {
        seen.add(a.key);
        if (flags.baseline) continue;
        out(a.line);
        appendFileSync(join(stateDir, 'detections.tsv'), [new Date().toISOString(), a.key, a.kind, a.eventAt ? new Date(a.eventAt).toISOString() : '', a.eventAt ? minutes(Date.now() - a.eventAt) : ''].join('\t') + '\n');
      }
      ensureState();
      writeFileSync(seenFile, JSON.stringify([...seen], null, 0) + '\n');
      if (flags.baseline) { out(`baseline: ${alerts.length} existing alert(s) marked as seen`); return 0; }
      return alerts.length ? 4 : 0;
    }
    case 'changed': {
      // Mechanical pre-check, no LLM: has anything a tick cares about changed since the last tick finished?
      // Exit 0 = changed (run a tick), 10 = unchanged (skip, costs no tokens). `changed --mark` stores the fingerprint.
      const fp = createHash('sha256').update(JSON.stringify({
        plans: plans.map((p) => [p.id, p.status, p.priority, p.blockedBy, p.footprint, p.base]),
        leaders: state.leaders,
        queue: readQueue(stateDir).filter((q) => !q.done).length,
      })).digest('hex');
      const file = join(stateDir, 'fingerprint');
      const last = existsSync(file) ? readFileSync(file, 'utf8').trim() : '';
      if (flags.mark) { ensureState(); writeFileSync(file, fp + '\n'); out('fingerprint stored'); return 0; }
      if (fp === last) { out('unchanged'); return 10; }
      out('changed');
      return 0;
    }
    case 'queue': {
      // Owner decision queue: what only the owner can decide. One JSON line per item.
      const [action, ...qargs] = args;
      const items = readQueue(stateDir);
      if (action === 'add') {
        const [plan, ...text] = qargs;
        if (!plan || !text.length) { out('usage: queue add <plan> <what is happening / options / recommendation>'); return 2; }
        const id = String(items.length + 1);
        ensureState();
        appendFileSync(join(stateDir, 'queue.jsonl'), JSON.stringify({ id, plan, text: text.join(' '), kind: flags.kind ?? 'unknown', at: flags.at ?? new Date().toISOString(), done: false }) + '\n');
        out(`queued ${id}`);
        return 0;
      }
      if (action === 'done') {
        const item = items.find((q) => q.id === qargs[0]);
        if (!item) { out(`no queue item ${qargs[0]}`); return 2; }
        item.done = true;
        item.answeredAt = flags.at ?? new Date().toISOString();
        writeFileSync(join(stateDir, 'queue.jsonl'), items.map((q) => JSON.stringify(q)).join('\n') + '\n');
        out(`closed ${item.id}`);
        return 0;
      }
      if (action === 'list' || action === undefined) {
        for (const q of items.filter((x) => !x.done)) out(`${q.id}\t${q.plan}\t${q.text}`);
        return 0;
      }
      out('usage: queue <add|list|done>');
      return 2;
    }
    case 'lock': {
      // One supervisor tick at a time. A lock older than its ttl is taken over, so a dead tick never wedges the loop.
      const [action] = args;
      const file = join(stateDir, 'lock.json');
      ensureState();
      if (action === 'release') { if (existsSync(file)) unlinkSync(file); out('lock released'); return 0; }
      if (action !== 'acquire') { out('usage: lock <acquire|release> [--ttl-min N]'); return 2; }
      const ttlMs = Number(flags['ttl-min'] ?? 30) * 60_000;
      const take = () => writeFileSync(file, JSON.stringify({ at: Date.now(), ttlMs }), { flag: 'wx' });
      try { take(); out('lock acquired'); return 0; } catch (e) { if (e.code !== 'EEXIST') throw e; }
      const held = JSON.parse(readFileSync(file, 'utf8'));
      if (Date.now() - held.at < held.ttlMs) { out(`lock held since ${new Date(held.at).toISOString()}`); return 3; }
      unlinkSync(file);
      try { take(); out('lock taken over (previous tick expired)'); return 0; } catch (e) { if (e.code !== 'EEXIST') throw e; out('lock lost to another tick'); return 3; }
    }
    case 'log': {
      const [note, ...kv] = args;
      ensureState();
      appendFileSync(join(stateDir, 'ticks.tsv'), [new Date().toISOString(), note ?? '', ...kv].join('\t') + '\n');
      return 0;
    }
    default:
      out('usage: plan-board.mjs <check|eligible|render|claim|release|health|watch|config|doctor|verify|event|sessions|report|changed|queue|lock|log> [--root plans] [--max-running N] [--json] [--write]');
      return 2;
  }
}

if (import.meta.url === `file://${process.argv[1]}`) process.exit(main(process.argv.slice(2)));
